SELECT percent_rank() OVER (ORDER BY AVG(o.value)) AS percentile_rank FROM omr o JOIN icustays s ON o.subject_id = s.subject_id WHERE o.result_name = 'SpO2' AND s.stay_id IN (SELECT stay_id FROM icustays WHERE subject_id = o.subject_id AND intime <= o.charttime AND outtime >= o.charttime) AND s.subject_id = 757071 AND s.stay_id IN (SELECT stay_id FROM icustays WHERE age >= 87 AND age <= 97) AND o.charttime <= '2020-01-01' + interval '24 hours' AND o.value >= 88 GROUP BY o.subject_id, o.stay_id;